const labels={pending:'Pending review',changes:'Changes requested',approved:'Approved',rejected:'Rejected'};
let drivers=readStored(),selected=null,activeDoc=null,currentView='pending';
function readStored(){try{return JSON.parse(localStorage.getItem('routecrewApplications'))||[]}catch{return[]}}
function persist(){localStorage.setItem('routecrewApplications',JSON.stringify(drivers))}
function initials(name){return name.split(/\s+/).map(v=>v[0]).slice(0,2).join('').toUpperCase()||'DR'}
function timeLabel(value){if(!value)return '—';const [h,m]=value.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`}
function sizeLabel(bytes){return bytes>=1048576?`${(bytes/1048576).toFixed(1)} MB`:`${Math.round(bytes/1024)} KB`}
function filteredDrivers(){const term=document.querySelector('#searchDrivers').value.toLowerCase();return drivers.filter(d=>{const viewMatch=currentView==='audit'||(currentView==='pending'?(d.status==='pending'||d.status==='rejected'):d.status===currentView);return viewMatch&&`${d.name} ${d.phone} ${d.vehicle} ${d.id}`.toLowerCase().includes(term)})}
function renderQueue(){const shown=filteredDrivers();document.querySelector('#queueCount').textContent=`${shown.length} result${shown.length===1?'':'s'}`;document.querySelector('#driverQueue').innerHTML=shown.map(d=>`<button class="queue-item ${selected&&d.id===selected.id?'selected':''}" data-id="${d.id}"><span class="queue-avatar">${initials(d.name)}</span><span class="queue-copy"><strong>${d.name}</strong><span>${d.vehicle||'Vehicle not provided'}</span><small>${currentView==='audit'?(d.audit?.at(-1)?.action||labels[d.status]):labels[d.status]}</small></span><span class="queue-age">${new Date(d.submittedAt).toLocaleDateString()}</span></button>`).join('')||'<p style="padding:20px;color:#718078">No applications in this section.</p>';document.querySelectorAll('.queue-item').forEach(b=>b.onclick=()=>selectDriver(b.dataset.id));const pending=drivers.filter(d=>d.status==='pending').length;document.querySelector('#pendingCount').textContent=`${pending} application${pending===1?'':'s'}`;document.querySelector('#navCount').textContent=pending;if(selected&&!shown.some(d=>d.id===selected.id))clearSelection()}
function clearSelection(){selected=null;document.querySelector('#reviewPanel').classList.add('empty')}
function selectDriver(id){selected=drivers.find(d=>d.id===id);if(!selected)return;document.querySelector('#reviewPanel').classList.remove('empty');const values={driverName:selected.name,driverAvatar:initials(selected.name),driverInfo:`${selected.id} · ${selected.phone} · ${selected.vehicle}`,companyName:selected.company||'Not assigned',vehicleType:`${selected.type||'Vehicle'} · ${selected.capacity||'—'} seats`,driverDob:selected.dob||'—',experienceYears:`${selected.experience||'—'} years`,morningTimeDisplay:timeLabel(selected.morningTime),eveningTimeDisplay:timeLabel(selected.eveningTime),extraTripsDisplay:selected.acceptsExtraTrips?'Interested':'Not interested',appliedDate:new Date(selected.submittedAt).toLocaleString()};Object.entries(values).forEach(([id,value])=>document.querySelector('#'+id).textContent=value);const badge=document.querySelector('#driverStatus');badge.textContent=labels[selected.status];badge.className=`badge ${selected.status}`;document.querySelector('#reviewNote').value=selected.reviewNote||'';renderDocuments();renderQueue()}
function renderDocuments(){const list=selected.documents||[],verified=list.filter(d=>d.state==='verified').length;document.querySelector('#verifiedProgress').textContent=`${verified} of ${list.length} verified`;document.querySelector('#approveProfile').disabled=!list.length||verified!==list.length;document.querySelector('#documentList').innerHTML=list.map((d,i)=>`<div class="document-row"><span class="doc-icon">▤</span><span class="doc-copy"><b>${d.type}</b><small>${d.file} · ${sizeLabel(d.size)}</small></span><span class="doc-state ${d.state}">${d.state==='verified'?'Verified':d.state==='reupload'?'Re-upload needed':'Awaiting review'}</span><button class="view-doc" data-doc="${i}">Open</button></div>`).join('')||'<p style="padding:16px;color:#718078">No document metadata was submitted.</p>';document.querySelectorAll('.view-doc').forEach(b=>b.onclick=()=>openDocument(+b.dataset.doc))}
function openDocument(index){activeDoc=index;const d=selected.documents[index];document.querySelector('#modalType').textContent=d.type.toUpperCase();document.querySelector('#modalName').textContent=selected.name;document.querySelector('#previewDocName').textContent=selected.name.toUpperCase();document.querySelector('#previewInitials').textContent=initials(selected.name);document.querySelector('#previewFile').textContent=d.file;document.querySelector('#previewSize').textContent=sizeLabel(d.size);document.querySelector('#modalVerify').textContent=d.state==='verified'?'Verified ✓':'Mark as verified';document.querySelector('#documentModal').showModal()}
function audit(action){selected.audit=selected.audit||[];selected.audit.push({action,at:new Date().toISOString()})}
function setDocState(state){selected.documents[activeDoc].state=state;audit(`${selected.documents[activeDoc].type}: ${state==='verified'?'verified':'re-upload requested'}`);persist();document.querySelector('#documentModal').close();renderDocuments();notify(state==='verified'?'Document marked as verified.':'Re-upload requested.')}
function decide(status){const note=document.querySelector('#reviewNote').value.trim();if((status==='rejected'||status==='changes')&&!note){notify('Add a note explaining this decision.');document.querySelector('#reviewNote').focus();return}selected.status=status;selected.reviewNote=note;audit(labels[status]);persist();renderQueue();selectDriver(selected.id);notify(status==='approved'?'Driver approved.':status==='rejected'?'Driver profile rejected.':'Changes requested from driver.')}
function changeView(view){currentView=view;document.querySelectorAll('.admin-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const titles={pending:['Pending verification','Review submitted driver details and documents before activation.'],approved:['Verified drivers','Drivers approved by an authorized verifier.'],changes:['Re-upload requests','Applications waiting for corrected documents.'],audit:['Audit history','Review recorded submission and verification actions.']};document.querySelector('#viewTitle').textContent=titles[view][0];document.querySelector('#viewDescription').textContent=titles[view][1];document.querySelector('#statusFilter').value='all';clearSelection();renderQueue()}
function notify(message){const toast=document.querySelector('#toast');toast.textContent=message;toast.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>toast.classList.remove('show'),2600)}
document.querySelector('#searchDrivers').oninput=renderQueue;document.querySelector('#statusFilter').onchange=e=>{if(e.target.value!=='all')currentView=e.target.value;renderQueue()};document.querySelectorAll('.admin-nav button').forEach(b=>b.onclick=()=>changeView(b.dataset.view));document.querySelector('#closeModal').onclick=()=>document.querySelector('#documentModal').close();document.querySelector('#modalVerify').onclick=()=>setDocState('verified');document.querySelector('#modalReupload').onclick=()=>setDocState('reupload');document.querySelector('#approveProfile').onclick=()=>decide('approved');document.querySelector('#rejectProfile').onclick=()=>decide('rejected');document.querySelector('#requestChanges').onclick=()=>decide('changes');renderQueue();if(filteredDrivers()[0])selectDriver(filteredDrivers()[0].id);
